sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.twin = {
    riskScore: 35,
    riskLevel: "Medium Risk",
    lastCalculated: "2026-08-07",
    riskReasons: [
      {
        title: "Deadline Proximity",
        points: 20,
        description: "CPT start date is within 18 days and advisor approval is still pending."
      },
      {
        title: "Missing Required Document",
        points: 15,
        description: "Academic Advisor Approval Form has not been uploaded for CASE0010011."
      }
    ]
  };
};

sp_widget.css:
/* =========================================================
   VISA GUARDIAN AI
   STUDENT COMPLIANCE DIGITAL TWIN
   PREMIUM ENTERPRISE DASHBOARD UI
   ========================================================= */


/* =========================================================
   GLOBAL
   ========================================================= */

.vg-twin-page,
.vg-twin-page *,
.vg-twin-page *::before,
.vg-twin-page *::after {
    box-sizing: border-box;
}

.vg-twin-page {
    width: 100%;
    min-height: 100vh;

    padding: 0;

    background:
        radial-gradient(
            circle at 95% 0%,
            rgba(35, 126, 205, 0.08),
            transparent 24%
        ),
        radial-gradient(
            circle at 0% 100%,
            rgba(111, 76, 180, 0.045),
            transparent 24%
        ),
        #f4f7fb;

    font-family:
        "Segoe UI",
        Arial,
        Helvetica,
        sans-serif;

    color: #17395f;
}


/* =========================================================
   PAGE HEADER
   ========================================================= */

.vg-twin-header {
    position: relative;

    width: 100%;
    min-height: 88px;

    padding: 15px 25px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    overflow: hidden;

    border-radius: 14px;

    background:
        linear-gradient(
            120deg,
            #06366b 0%,
            #08477f 48%,
            #125c99 100%
        );

    color: #ffffff;

    box-shadow:
        0 10px 26px rgba(0, 48, 95, 0.14),
        0 2px 7px rgba(0, 48, 95, 0.08);
}


/* Header decorative glow */

.vg-twin-header::before {
    content: "";

    position: absolute;

    width: 280px;
    height: 280px;

    right: -90px;
    top: -175px;

    border-radius: 50%;

    background:
        rgba(78, 169, 239, 0.13);

    pointer-events: none;
}


.vg-twin-header::after {
    content: "";

    position: absolute;

    width: 170px;
    height: 170px;

    left: 48%;
    bottom: -135px;

    border-radius: 50%;

    background:
        rgba(255, 255, 255, 0.035);

    pointer-events: none;
}


/* =========================================================
   HEADER LEFT
   ========================================================= */

.vg-twin-header-left {
    position: relative;
    z-index: 2;

    display: flex;
    align-items: center;

    min-width: 0;
}


/* =========================================================
   HEADER ICON
   ========================================================= */

.vg-twin-header-icon {
    position: relative;

    width: 60px;
    height: 60px;

    min-width: 60px;

    margin-right: 16px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background:
        linear-gradient(
            145deg,
            rgba(255,255,255,.15),
            rgba(255,255,255,.07)
        );

    border:
        1px solid
        rgba(255,255,255,.17);

    box-shadow:
        inset 0 1px 0
        rgba(255,255,255,.12);

    font-size: 28px;
}


/* =========================================================
   TITLE
   ========================================================= */

.vg-twin-title {
    font-size: 28px;

    font-weight: 750;

    line-height: 34px;

    letter-spacing: -0.4px;

    color: #ffffff;
}


/* =========================================================
   SUBTITLE
   ========================================================= */

.vg-twin-subtitle {
    margin-top: 4px;

    font-size: 13px;

    line-height: 18px;

    color: #d8e8f7;
}


/* =========================================================
   LIVE STATUS
   ========================================================= */

.vg-twin-live-status {
    position: relative;
    z-index: 2;

    display: inline-flex;
    align-items: center;

    gap: 9px;

    padding: 9px 15px;

    border-radius: 22px;

    background:
        rgba(255,255,255,.10);

    border:
        1px solid
        rgba(255,255,255,.22);

    color: #ffffff;

    font-size: 12px;

    font-weight: 650;

    white-space: nowrap;

    box-shadow:
        inset 0 1px 0
        rgba(255,255,255,.06);
}


/* =========================================================
   LIVE DOT
   ========================================================= */

.vg-live-dot {
    width: 9px;
    height: 9px;

    min-width: 9px;

    border-radius: 50%;

    background: #31c47a;

    box-shadow:
        0 0 0 4px
        rgba(49,196,122,.14);
}


/* =========================================================
   ERROR
   ========================================================= */

.vg-twin-error {
    margin-top: 15px;

    padding: 13px 16px;

    display: flex;
    align-items: center;

    gap: 9px;

    background:
        #fff3f3;

    border:
        1px solid
        #efc1c1;

    border-left:
        4px solid
        #d9534f;

    border-radius: 9px;

    color: #c62828;

    font-size: 13px;

    box-shadow:
        0 3px 9px
        rgba(160,40,40,.04);
}


/* =========================================================
   STUDENT CONTEXT
   ========================================================= */

.vg-twin-student-context {
    margin-top: 14px;

    padding: 11px 18px;

    display: flex;
    align-items: center;

    background:
        rgba(255,255,255,.96);

    border:
        1px solid
        #d7e2ed;

    border-radius: 10px;

    box-shadow:
        0 4px 12px
        rgba(0,40,80,.045);
}


/* =========================================================
   CONTEXT ITEM
   ========================================================= */

.vg-student-context-item {
    display: flex;
    align-items: center;

    gap: 8px;

    min-width: 0;
}


/* =========================================================
   CONTEXT LABEL
   ========================================================= */

.vg-context-label {
    color: #7d8fa3;

    font-size: 10px;

    font-weight: 650;

    text-transform: uppercase;

    letter-spacing: .55px;
}


/* =========================================================
   CONTEXT VALUE
   ========================================================= */

.vg-student-context-item strong {
    color: #123f77;

    font-size: 12px;

    font-weight: 750;
}


/* =========================================================
   CONTEXT DIVIDER
   ========================================================= */

.vg-student-context-divider {
    width: 1px;

    height: 23px;

    margin: 0 19px;

    background:
        #dce5ef;
}


/* =========================================================
   SUMMARY GRID
   ========================================================= */

.vg-twin-summary-grid {
    width: 100%;

    margin-top: 20px;

    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 18px;
}


/* =========================================================
   SUMMARY CARD
   ========================================================= */

.vg-twin-summary-card {
    position: relative;

    min-height: 169px;

    padding: 18px 20px 17px;

    background:
        #ffffff;

    border:
        1px solid
        #d7e2ed;

    border-radius:
        12px;

    overflow:
        hidden;

    box-shadow:
        0 5px 15px
        rgba(0,40,80,.055);

    transition:
        transform .2s ease,
        box-shadow .2s ease,
        border-color .2s ease;
}


.vg-twin-summary-card:hover {
    transform:
        translateY(-2px);

    border-color:
        #c5d8e9;

    box-shadow:
        0 10px 23px
        rgba(0,40,80,.09);
}


/* =========================================================
   SUMMARY CARD ACCENT
   ========================================================= */

.vg-twin-summary-card::before {
    content: "";

    position: absolute;

    left: 0;
    top: 0;
    bottom: 0;

    width: 4px;
}


.score-card::before {
    background: #35ad72;
}


.visa-card::before {
    background: #347fc9;
}


.risk-card::before {
    background: #e5a52f;
}


.deadline-card::before {
    background: #7955bd;
}


/* =========================================================
   SUMMARY TOP
   ========================================================= */

.vg-summary-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;

    gap: 10px;
}


.vg-summary-top > div:first-child {
    flex: 1;

    min-width: 0;

    padding-right: 6px;
}


/* =========================================================
   SUMMARY LABEL
   ========================================================= */

.vg-summary-label {
    color: #60758c;

    font-size: 12px;

    font-weight: 650;
}


/* =========================================================
   SUMMARY VALUE
   ========================================================= */

.vg-summary-value {
    margin-top: 8px;

    color: #123f77;

    font-size: 27px;

    font-weight: 750;

    line-height: 31px;

    white-space: normal;

    overflow-wrap: normal;
}


/* Visa status */

.visa-card .vg-summary-value {
    max-width: 130px;

    font-size: 21px;

    line-height: 27px;

    letter-spacing: -.2px;
}


/* Deadline */

.deadline-card .vg-summary-value {
    font-size: 25px;

    line-height: 29px;

    white-space: nowrap;
}


/* =========================================================
   SUMMARY ICON
   ========================================================= */

.vg-summary-icon {
    width: 50px;
    height: 50px;

    min-width: 50px;

    border-radius: 11px;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 21px;
}


.score-icon {
    background: #e5f6ed;
    color: #28a66b;
}


.visa-icon {
    background: #e7f0fb;
    color: #2c7ac2;
}


.risk-icon {
    background: #fff0d6;
    color: #d89218;
}


.deadline-icon {
    background: #f0eafa;
    color: #7955bd;
}


/* =========================================================
   SCORE BAR
   ========================================================= */

.vg-score-bar {
    width: 100%;

    height: 7px;

    margin-top: 15px;

    overflow: hidden;

    border-radius: 10px;

    background:
        #e5ebf1;
}


.vg-score-progress {
    height: 100%;

    border-radius: 10px;

    background:
        #35ad72;

    transition:
        width .4s ease;
}


/* =========================================================
   SUMMARY STATUS
   ========================================================= */

.vg-summary-status {
    margin-top: 8px;

    display: flex;
    align-items: center;

    gap: 6px;

    font-size: 11px;

    font-weight: 650;
}


.vg-summary-status span {
    width: 7px;
    height: 7px;

    min-width: 7px;

    border-radius: 50%;

    display: inline-block;
}


.vg-summary-status.success {
    color: #24935b;
}


.vg-summary-status.success span {
    background: #2db375;
}


.vg-summary-status.warning {
    color: #d89016;
}


.vg-summary-status.warning span {
    background: #e6a42c;
}


.vg-summary-status.danger {
    color: #d34c4c;
}


.vg-summary-status.danger span {
    background: #d9534f;
}


/* =========================================================
   SUMMARY DESCRIPTION
   ========================================================= */

.vg-summary-description {
    margin-top: 9px;

    color: #7b90a6;

    font-size: 11px;

    line-height: 17px;
}


/* =========================================================
   MAIN TWO-COLUMN AREA
   ========================================================= */

.vg-twin-main-grid {
    margin-top: 20px;

    display: grid;

    grid-template-columns:
        minmax(0, 1fr)
        minmax(0, 1fr);

    gap: 18px;

    align-items: start;
}


/* =========================================================
   GENERAL CARD
   ========================================================= */

.vg-twin-card {
    background:
        #ffffff;

    border:
        1px solid
        #d7e2ed;

    border-radius:
        12px;

    overflow:
        hidden;

    box-shadow:
        0 5px 15px
        rgba(0,40,80,.05);
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.vg-twin-card-header {
    min-height: 68px;

    padding:
        12px 19px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    gap: 12px;

    border-bottom:
        1px solid
        #dce5ef;

    background:
        linear-gradient(
            180deg,
            #ffffff,
            #fbfdff
        );
}


/* =========================================================
   CARD HEADING
   ========================================================= */

.vg-card-heading {
    display: flex;

    align-items: center;

    min-width: 0;
}


/* =========================================================
   CARD ICON
   ========================================================= */

.vg-card-heading-icon {
    width: 44px;
    height: 44px;

    min-width: 44px;

    margin-right: 12px;

    border-radius: 10px;

    background:
        #edf4fb;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 19px;
}


/* =========================================================
   CARD TITLE
   ========================================================= */

.vg-card-title {
    color: #123f77;

    font-size: 17px;

    font-weight: 750;

    line-height: 21px;
}


/* =========================================================
   CARD SUBTITLE
   ========================================================= */

.vg-card-subtitle {
    margin-top: 3px;

    color: #8295a9;

    font-size: 11px;

    line-height: 15px;
}


/* =========================================================
   DOCUMENT COUNT
   ========================================================= */

.vg-document-count {
    padding:
        6px 11px;

    border-radius:
        17px;

    background:
        #edf4fb;

    color:
        #1760a2;

    font-size:
        12px;

    font-weight:
        750;

    white-space:
        nowrap;
}


/* =========================================================
   DOCUMENT PROGRESS
   ========================================================= */

.vg-document-progress {
    height: 8px;

    margin:
        17px 20px 8px;

    overflow:
        hidden;

    border-radius:
        10px;

    background:
        #e4ebf1;
}


.vg-document-progress-fill {
    height: 100%;

    border-radius: 10px;

    background:
        #35ad72;

    transition:
        width .4s ease;
}


/* =========================================================
   DOCUMENT SUMMARY
   ========================================================= */

.vg-document-summary {
    padding:
        0 20px 9px;

    display:
        flex;

    justify-content:
        space-between;

    gap:
        10px;

    color:
        #60758b;

    font-size:
        11px;

    font-weight:
        600;
}


.vg-document-missing {
    color:
        #d99016;
}


.vg-document-complete {
    color:
        #24975d;
}


/* =========================================================
   DOCUMENT INSIGHT
   ========================================================= */

.vg-document-insight {
    margin:
        12px 20px 7px;

    padding:
        14px;

    display:
        flex;

    align-items:
        center;

    gap:
        12px;

    border:
        1px solid
        #dfe8f0;

    border-radius:
        10px;

    background:
        linear-gradient(
            135deg,
            #f8fbfe,
            #f5f9fd
        );
}


.vg-document-insight-icon {
    width: 39px;
    height: 39px;

    min-width: 39px;

    border-radius: 9px;

    display: flex;

    align-items: center;

    justify-content: center;

    background:
        #edf4fb;

    font-size:
        17px;
}


.vg-document-insight-content {
    min-width: 0;
}


.vg-document-insight-title {
    color:
        #214766;

    font-size:
        12px;

    font-weight:
        750;

    line-height:
        17px;
}


.vg-document-insight-description {
    margin-top:
        3px;

    color:
        #8294a8;

    font-size:
        10px;

    line-height:
        15px;
}


/* =========================================================
   DOCUMENT LIST
   ========================================================= */

.vg-document-list {
    padding:
        0 20px 9px;
}


/* =========================================================
   DOCUMENT ROW
   ========================================================= */

.vg-document-row {
    min-height:
        46px;

    padding:
        8px 0;

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    gap:
        10px;

    border-bottom:
        1px solid
        #edf1f5;
}


.vg-document-row:last-child {
    border-bottom:
        none;
}


/* =========================================================
   DOCUMENT NAME
   ========================================================= */

.vg-document-name {
    display:
        flex;

    align-items:
        center;

    gap:
        9px;

    min-width:
        0;

    color:
        #304c68;

    font-size:
        12px;

    font-weight:
        650;
}


/* =========================================================
   CHECK ICON
   ========================================================= */

.vg-check {
    width:
        24px;

    height:
        24px;

    min-width:
        24px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        50%;

    background:
        #e3f6eb;

    color:
        #26a568;

    font-size:
        12px;

    font-weight:
        750;
}


/* =========================================================
   WARNING ICON
   ========================================================= */

.vg-warning {
    width:
        24px;

    height:
        24px;

    min-width:
        24px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        50%;

    background:
        #fff0d5;

    color:
        #d89016;

    font-size:
        12px;

    font-weight:
        750;
}


/* =========================================================
   DOCUMENT STATUS
   ========================================================= */

.vg-document-status {
    padding:
        5px 9px;

    border-radius:
        13px;

    font-size:
        10px;

    font-weight:
        650;

    white-space:
        nowrap;
}


.vg-document-status.complete {
    background:
        #e5f6ec;

    color:
        #258e59;
}


.vg-document-status.pending {
    background:
        #fff0d8;

    color:
        #d18a12;
}


/* =========================================================
   SECONDARY BUTTON
   ========================================================= */

.vg-twin-secondary-button {
    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        center;

    margin:
        8px 20px 18px;

    padding:
        9px 14px;

    border:
        1px solid
        #bfd3e6;

    border-radius:
        7px;

    background:
        #ffffff;

    color:
        #15528a !important;

    font-size:
        11px;

    font-weight:
        650;

    text-decoration:
        none !important;

    cursor:
        pointer;

    transition:
        all .2s ease;
}


.vg-twin-secondary-button:hover {
    background:
        #eef5fc;

    border-color:
        #8db4d6;

    color:
        #0c4d85 !important;

    box-shadow:
        0 4px 10px
        rgba(25,90,140,.08);

    transform:
        translateY(-1px);

    text-decoration:
        none !important;
}


/* =========================================================
   DEADLINE LIST
   ========================================================= */

.vg-deadline-list {
    padding:
        4px 20px 2px;
}


/* =========================================================
   DEADLINE ITEM
   ========================================================= */

.vg-deadline-item {
    min-height:
        70px;

    padding:
        10px 0;

    display:
        flex;

    align-items:
        center;

    gap:
        11px;

    border-bottom:
        1px solid
        #e8edf2;
}


.vg-deadline-item:last-child {
    border-bottom:
        none;
}


/* =========================================================
   DEADLINE ICON
   ========================================================= */

.vg-deadline-icon {
    width:
        41px;

    height:
        41px;

    min-width:
        41px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        10px;

    background:
        #edf4fb;

    color:
        #3b78ad;

    font-size:
        17px;
}


.vg-deadline-icon.urgent-icon {
    background:
        #fff0d7;

    color:
        #df971a;
}


/* =========================================================
   DEADLINE CONTENT
   ========================================================= */

.vg-deadline-content {
    flex:
        1;

    min-width:
        0;
}


.vg-deadline-title {
    color:
        #214766;

    font-size:
        12px;

    font-weight:
        750;

    white-space:
        nowrap;

    overflow:
        hidden;

    text-overflow:
        ellipsis;
}


.vg-deadline-case {
    margin-top:
        2px;

    color:
        #8294a8;

    font-size:
        10px;
}


.vg-deadline-date {
    margin-top:
        3px;

    color:
        #657d95;

    font-size:
        10px;

    line-height:
        15px;
}


/* =========================================================
   DEADLINE BADGES
   ========================================================= */

.vg-deadline-badge {
    padding:
        6px 10px;

    border-radius:
        6px;

    font-size:
        10px;

    font-weight:
        650;

    white-space:
        nowrap;
}


.urgent-badge {
    background:
        #fff0d7;

    color:
        #d68c0e;
}


.warning-badge {
    background:
        #fff4df;

    color:
        #d79622;
}


.normal-badge {
    background:
        #e5f6ec;

    color:
        #258e59;
}


/* =========================================================
   VIEW ALL
   ========================================================= */

.vg-view-all {
    color:
        #3175b5;

    font-size:
        10px;

    font-weight:
        650;
}


/* =========================================================
   RISK EXPLANATION
   ========================================================= */

.vg-risk-explanation {
    margin-top:
        20px;
}


/* =========================================================
   RISK WEIGHTS
   ========================================================= */

.vg-risk-weight-info {
    color:
        #59738d;

    font-size:
        11px;

    white-space:
        nowrap;
}


/* =========================================================
   RISK CONTENT
   ========================================================= */

.vg-risk-content {
    padding:
        25px 28px;

    display:
        grid;

    grid-template-columns:
        310px
        minmax(0, 1fr);

    gap:
        38px;

    align-items:
        center;
}


/* =========================================================
   RISK SCORE SECTION
   ========================================================= */

.vg-risk-score-section {
    text-align:
        center;

    padding:
        5px 15px;
}


/* =========================================================
   RISK SCORE
   ========================================================= */

.vg-risk-score {
    color:
        #123f77;

    font-size:
        54px;

    font-weight:
        750;

    line-height:
        58px;

    letter-spacing:
        -1px;
}


.vg-risk-score span {
    color:
        #7c91a7;

    font-size:
        17px;

    font-weight:
        500;

    letter-spacing:
        0;
}


/* =========================================================
   RISK LEVEL
   ========================================================= */

.vg-risk-level {
    margin-top:
        8px;

    font-size:
        12px;

    font-weight:
        750;

    letter-spacing:
        .2px;
}


.risk-level-low {
