sp_widget.script:
(function() {

    // =========================================================
    // VISA GUARDIAN AI
    // STUDENT COMPLIANCE DIGITAL TWIN
    // =========================================================


    // =========================================================
    // INITIAL DATA
    // =========================================================

    data.error = "";

    data.student = null;

    data.summary = {
        compliance_score: 0,
        risk_score: 0,
        risk_level: "Low",
        visa_status: "Not Available",
        next_deadline: null,
        active_cases: 0,

        document_completion: 0,
        total_documents: 0,
        completed_documents: 0,
        missing_documents: 0,

        sla_breaches: 0,
        deadline_risk: 0,
        document_risk: 0,
        sla_risk: 0
    };

    data.documents = {
        total: 0,
        completed: 0,
        missing: 0,
        percentage: 0,
        list: []
    };

    data.deadlines = [];

    data.compliance_state = [];

    data.risk = {
        score: 0,
        level: "Low",
        explanation: []
    };

    data.recommendation = "";

    data.cases = [];

    data.latest_assessment = null;


    // =========================================================
    // 1. FIND LOGGED-IN STUDENT
    // =========================================================

    var student =
        new GlideRecord(
            "x_snc_visaguardi_0_student_profile"
        );

    var profileFound = false;


    var sessionStudentSysId =
        gs.getSession().getClientData(
            "vg_student_sys_id"
        );

    var sessionStudentUserName =
        gs.getSession().getClientData(
            "vg_student_user_name"
        );


    // ---------------------------------------------------------
    // 1A. SESSION STUDENT SYS ID
    // ---------------------------------------------------------

    if (sessionStudentSysId) {

        if (
            student.get(
                sessionStudentSysId
            )
        ) {

            profileFound = true;
        }
    }


    // ---------------------------------------------------------
    // 1B. SESSION USER NAME
    // ---------------------------------------------------------

    if (
        !profileFound &&
        sessionStudentUserName
    ) {

        student =
            new GlideRecord(
                "x_snc_visaguardi_0_student_profile"
            );

        student.addQuery(
            "user_name",
            sessionStudentUserName
        );

        student.setLimit(1);

        student.query();

        if (student.next()) {

            profileFound = true;
        }
    }


    // ---------------------------------------------------------
    // 1C. SERVICENOW USER REFERENCE
    // ---------------------------------------------------------

    if (!profileFound) {

        var userSysId =
            gs.getUserID();

        if (userSysId) {

            student =
                new GlideRecord(
                    "x_snc_visaguardi_0_student_profile"
                );

            student.addQuery(
                "user",
                userSysId
            );

            student.setLimit(1);

            student.query();

            if (student.next()) {

                profileFound = true;
            }
        }
    }


    // ---------------------------------------------------------
    // 1D. SERVICENOW USER NAME
    // ---------------------------------------------------------

    if (!profileFound) {

        student =
            new GlideRecord(
                "x_snc_visaguardi_0_student_profile"
            );

        student.addQuery(
            "user_name",
            gs.getUserName()
        );

        student.setLimit(1);

        student.query();

        if (student.next()) {

            profileFound = true;
        }
    }


    // =========================================================
    // PROFILE NOT FOUND
    // =========================================================

    if (!profileFound) {

        data.error =
            "Student profile was not found for the logged-in student.";

        return;
    }


    // =========================================================
    // 2. STUDENT INFORMATION
    // =========================================================

    data.student = {

        sys_id:
            student.getUniqueValue(),

        name:
            student.getDisplayValue("name"),

        first_name:
            student.getValue("first_name"),

        last_name:
            student.getValue("last_name"),

        student_id:
            student.getValue("student_id"),

        email:
            student.getValue("email"),

        visa_type:
            student.getDisplayValue("visa_type"),

        visa_status:
            student.getDisplayValue(
                "current_visa_status"
            ),

        sevis_id:
            student.getValue("sevis_id"),

        university_name:
            student.getValue("university_name"),

        degree_program:
            student.getValue("degree_program"),

        degree_level:
            student.getDisplayValue(
                "degree_level"
            )
    };


    // =========================================================
    // 3. HELPER FUNCTIONS
    // =========================================================


    /*
     * Converts values such as:
     *
     * new_visa_application
     * New Visa Application
     * NEW VISA APPLICATION
     *
     * into the same comparable format.
     */
    function normalize(value) {

        if (
            value === null ||
            value === undefined
        ) {

            return "";
        }

        return String(value)
            .trim()
            .toLowerCase()
            .replace(/[_-]+/g, " ")
            .replace(/\s+/g, " ");
    }


    /*
     * Converts a request/case type into
     * the category used by Document Configuration.
     */
    function normalizeCategory(value) {

        var result =
            normalize(value);

        /*
         * Remove common suffixes only when needed.
         */
        if (
            result === "cpt request"
        ) {
            result = "cpt application";
        }

        if (
            result === "opt request"
        ) {
            result = "opt application";
        }

        if (
            result === "visa request"
        ) {
            result = "visa renewal";
        }

        return result;
    }


    function numberValue(value) {

        var parsed =
            parseInt(
                value,
                10
            );

        if (isNaN(parsed)) {

            return 0;
        }

        return parsed;
    }


    function getDaysRemaining(dateValue) {

        if (!dateValue) {

            return null;
        }

        var today =
            new GlideDateTime();

        var due =
            new GlideDateTime(
                dateValue
            );

        var difference =
            due.getNumericValue() -
            today.getNumericValue();

        return Math.ceil(
            difference /
            (
                1000 *
                60 *
                60 *
                24
            )
        );
    }


    function getRiskLevel(score) {

        if (score >= 80) {

            return "Critical";
        }

        if (score >= 60) {

            return "High";
        }

        if (score >= 30) {

            return "Medium";
        }

        return "Low";
    }


    function hasValue(value) {

        return (
            value !== null &&
            value !== undefined &&
            String(value).trim() !== ""
        );
    }


    /*
     * A document is considered completed only when
     * it has been verified/approved/completed.
     *
     * Uploaded does NOT automatically mean verified.
     */
   /*
 * A document is considered completed if it is verified, approved,
 * uploaded, or submitted.
 */
function isCompletedDocument(doc) {
    var verificationStatus = normalize(doc.getDisplayValue("verification_status"));
    var documentStatus = normalize(doc.getDisplayValue("document_status"));

    if (
        verificationStatus === "verified" ||
        verificationStatus === "approved" ||
        verificationStatus === "complete" ||
        verificationStatus === "completed" ||
        verificationStatus === "uploaded" ||
        verificationStatus === "submitted" ||
        verificationStatus === "pending_verification"
    ) {
        return true;
    }

    if (
        documentStatus === "verified" ||
        documentStatus === "approved" ||
        documentStatus === "complete" ||
        documentStatus === "completed" ||
        documentStatus === "uploaded" ||
        documentStatus === "submitted" ||
        documentStatus === "pending_verification"
    ) {
        return true;
    }

    return false;
}

/*
 * A document is missing only when it has not been uploaded/submitted,
 * or has been rejected.
 */
function isMissingDocument(doc) {
    var verificationStatus = normalize(doc.getDisplayValue("verification_status"));
    var documentStatus = normalize(doc.getDisplayValue("document_status"));

    if (
        verificationStatus === "rejected" ||
        verificationStatus === "missing" ||
        verificationStatus === "required" ||
        verificationStatus === "not verified" ||
        verificationStatus === "not_verified"
    ) {
        return true;
    }

    if (
        documentStatus === "required" ||
        documentStatus === "missing" ||
        documentStatus === "rejected"
    ) {
        return true;
    }

    return false;
}

    /*
     * Gets the best category value from a Visa Case.
     *
     * Primary:
     *   visa_category
     *
     * Fallback:
     *   case_type
     */
    function getCaseCategory(caseGR) {

        var category = "";


        if (
            caseGR.isValidField(
                "visa_category"
            )
        ) {

            category =
                caseGR.getDisplayValue(
                    "visa_category"
                );

            if (!hasValue(category)) {

                category =
                    caseGR.getValue(
                        "visa_category"
                    );
            }
        }


        if (!hasValue(category)) {

            if (
                caseGR.isValidField(
                    "case_type"
                )
            ) {

                category =
                    caseGR.getDisplayValue(
                        "case_type"
                    );

                if (!hasValue(category)) {

                    category =
                        caseGR.getValue(
                            "case_type"
                        );
                }
            }
        }


        return category;
    }


    /*
     * Find matching document configuration
     * for a particular Visa Case.
     *
     * IMPORTANT:
     *
     * We DO NOT use case_type from the
     * configuration table because that field
     * does not exist there.
     *
     * We use:
     *
     * configuration.visa_category
     *
     * against:
     *
     * case.visa_category OR case.case_type
     */
    function getRequiredDocumentsForCase(
        caseGR,
        configurationRecords
    ) {

        var result = [];

        var caseCategory =
            normalizeCategory(
                getCaseCategory(
                    caseGR
                )
            );


        if (!hasValue(caseCategory)) {

            return result;
        }


        for (
            var configIndex = 0;
            configIndex <
            configurationRecords.length;
            configIndex++
        ) {

            var config =
                configurationRecords[
                    configIndex
                ];


            var configCategory =
                normalizeCategory(
                    config.visa_category
                );


            if (
                configCategory !==
                caseCategory
            ) {

                continue;
            }


            result.push({

                configuration_sys_id:
                    config.sys_id,

                case_sys_id:
                    caseGR.getUniqueValue(),

                case_number:
                    caseGR.getDisplayValue(
                        "number"
                    ),

                case_category:
                    getCaseCategory(
                        caseGR
                    ),

                document_type:
                    config.document_type,

                document_type_value:
                    config.document_type_value,

                document_name:
                    config.document_type,

                priority:
                    config.priority
            });
        }


        /*
         * Sort by priority.
         */
        result.sort(
            function(a, b) {

                return (
                    a.priority -
                    b.priority
                );
            }
        );


        return result;
    }


    // =========================================================
    // 4. GET ALL ACTIVE VISA CASES
    // =========================================================

    var caseGR =
        new GlideRecord(
            "x_snc_visaguardi_0_visa_case"
        );


    caseGR.addQuery(
        "student",
        student.getUniqueValue()
    );


    caseGR.addQuery(
        "active",
        true
    );


    caseGR.orderBy(
        "due_date"
    );


    caseGR.query();


    while (caseGR.next()) {

        var caseCategory =
            getCaseCategory(
                caseGR
            );


        var caseData = {

            sys_id:
                caseGR.getUniqueValue(),

            number:
                caseGR.getDisplayValue(
                    "number"
                ),

            case_type:
                caseGR.isValidField(
                    "case_type"
                )
                    ? caseGR.getDisplayValue(
                        "case_type"
                    )
                    : "",

            case_type_value:
                caseGR.isValidField(
                    "case_type"
                )
                    ? caseGR.getValue(
                        "case_type"
                    )
                    : "",

            visa_category:
                caseGR.isValidField(
                    "visa_category"
                )
                    ? caseGR.getDisplayValue(
                        "visa_category"
                    )
                    : "",

            visa_category_value:
                caseGR.isValidField(
                    "visa_category"
                )
                    ? caseGR.getValue(
                        "visa_category"
                    )
                    : "",

            category:
                caseCategory,

            status:
                caseGR.isValidField(
                    "state"
                )
                    ? caseGR.getDisplayValue(
                        "state"
                    )
                    : "",

            due_date:
                caseGR.isValidField(
                    "due_date"
                )
                    ? caseGR.getDisplayValue(
                        "due_date"
                    )
                    : "",

            due_date_value:
                caseGR.isValidField(
                    "due_date"
                )
                    ? caseGR.getValue(
                        "due_date"
                    )
                    : "",

            days_remaining:
                caseGR.isValidField(
                    "due_date"
                )
                    ? getDaysRemaining(
                        caseGR.getValue(
                            "due_date"
                        )
                    )
                    : null,

            compliance_score:
                caseGR.isValidField(
                    "compliance_score"
                )
                    ? numberValue(
                        caseGR.getValue(
                            "compliance_score"
                        )
                    )
                    : 0,

            risk_level:
                caseGR.isValidField(
                    "risk_level"
                )
                    ? caseGR.getDisplayValue(
                        "risk_level"
                    )
                    : "",

            missing_documents:
                caseGR.isValidField(
                    "missing_documents_count"
                )
                    ? numberValue(
                        caseGR.getValue(
                            "missing_documents_count"
                        )
                    )
                    : 0,

            made_sla:
                caseGR.isValidField(
                    "made_sla"
                )
                    ? caseGR.getValue(
                        "made_sla"
                    )
                    : ""
        };


        data.cases.push(
            caseData
        );
    }


    data.summary.active_cases =
        data.cases.length;


    // =========================================================
    // 5. NO ACTIVE CASES
    // =========================================================

    if (
        data.cases.length === 0
    ) {

        data.summary.visa_status =
            data.student.visa_status ||
            "No Active Case";

        data.summary.compliance_score =
            100;

        data.summary.risk_score =
            0;

        data.summary.risk_level =
            "Low";

        data.documents.percentage =
            100;

        data.risk.score =
            0;

        data.risk.level =
            "Low";

        data.recommendation =
            "You currently have no active visa cases.";

        return;
    }


    // =========================================================
    // 6. CASE IDS
    // =========================================================

    var caseIds = [];

    for (
        var caseIndex = 0;
        caseIndex <
        data.cases.length;
        caseIndex++
    ) {

        caseIds.push(
            data.cases[
                caseIndex
            ].sys_id
        );
    }


    // =========================================================
    // 7. FIND NEAREST DEADLINE
    // =========================================================

    var nearestDeadline =
        null;


    for (
        var deadlineIndex = 0;
        deadlineIndex <
        data.cases.length;
        deadlineIndex++
    ) {

        var currentCase =
            data.cases[
                deadlineIndex
            ];


        /*
         * Cases without a due date are not
         * considered for nearest deadline.
         */
        if (
            currentCase.days_remaining ===
            null
        ) {

            continue;
        }


        var deadline = {

            case_sys_id:
                currentCase.sys_id,

            case_number:
                currentCase.number,

            case_type:
                currentCase.category,

            due_date:
                currentCase.due_date,

            days_remaining:
                currentCase.days_remaining
        };


        data.deadlines.push(
            deadline
        );


        if (
            nearestDeadline === null ||
            currentCase.days_remaining <
            nearestDeadline.days_remaining
        ) {

            nearestDeadline =
                deadline;
        }
    }


    // =========================================================
    // 8. VISA STATUS
    // =========================================================

    data.summary.visa_status =
        data.student.visa_status ||
        "Active";


    // =========================================================
    // 9. NEXT DEADLINE
    // =========================================================

    if (nearestDeadline) {

        data.summary.next_deadline =
            nearestDeadline;
    }


    // =========================================================
    // 10. LOAD DOCUMENT CONFIGURATION
    //
    // ACTUAL TABLE STRUCTURE:
    //
    // Active
    // Visa Category
    // Document Type
    // Required
    // Priority
    //
    // We DO NOT use:
    // case_type
    // document_name
    // =========================================================

    var configurationGR =
        new GlideRecord(
            "x_snc_visaguardi_0_document_configuration"
        );


    configurationGR.addQuery(
        "active",
        true
    );


    configurationGR.addQuery(
        "required",
        true
    );


    configurationGR.orderBy(
        "priority"
    );


    configurationGR.query();


    var configurationRecords =
        [];


    while (
        configurationGR.next()
    ) {

        var documentTypeDisplay =
            configurationGR.getDisplayValue(
                "document_type"
            );

        var documentTypeValue =
            configurationGR.getValue(
                "document_type"
            );


        configurationRecords.push({

            sys_id:
                configurationGR.getUniqueValue(),

            visa_category:
                configurationGR.getDisplayValue(
                    "visa_category"
                ),

            visa_category_value:
                configurationGR.getValue(
                    "visa_category"
                ),

            document_type:
                documentTypeDisplay,

            document_type_value:
                documentTypeValue,

            priority:
                numberValue(
                    configurationGR.getValue(
                        "priority"
                    )
                )
        });
    }


    // =========================================================
    // 11. LOAD ACTUAL VISA DOCUMENTS
    //
    // Documents are always scoped to
    // their individual Visa Case.
    // =========================================================

    var documentGR =
        new GlideRecord(
            "x_snc_visaguardi_0_visa_document"
        );


    documentGR.addQuery(
        "visa_case",
        "IN",
        caseIds.join(",")
    );


    documentGR.query();


    var uploadedDocuments =
        [];


    while (
        documentGR.next()
    ) {

        var completed =
            isCompletedDocument(
                documentGR
            );


        var missing =
            isMissingDocument(
                documentGR
            );


        uploadedDocuments.push({

            sys_id:
                documentGR.getUniqueValue(),

            visa_case:
                documentGR.getValue(
                    "visa_case"
                ),

            visa_case_display:
                documentGR.getDisplayValue(
                    "visa_case"
                ),

            document_type:
                documentGR.getDisplayValue(
                    "document_type"
                ),

            document_type_value:
                documentGR.getValue(
                    "document_type"
                ),

            document_status:
                documentGR.getDisplayValue(
                    "document_status"
                ),

            verification_status:
                documentGR.getDisplayValue(
                    "verification_status"
                ),

            expiry_date:
                documentGR.getDisplayValue(
                    "expiry_date"
                ),

            completed:
                completed,

            missing:
                missing
        });
    }


    // =========================================================
    // 12. DOCUMENT COMPLETENESS
    //
    // IMPORTANT:
    //
    // We process EACH ACTIVE VISA CASE separately.
    //
    // Example:
    //
    // Case A → 5 required docs
    // Case B → 4 required docs
    //
    // They are NOT mixed together.
    // =========================================================

    var totalRequiredDocuments = 0;

    var totalCompletedDocuments = 0;

    var totalMissingDocuments = 0;


    for (
        var caseDocIndex = 0;
        caseDocIndex <
        data.cases.length;
        caseDocIndex++
    ) {

        var currentVisaCase =
            data.cases[
                caseDocIndex
            ];


        // -----------------------------------------------------
        // Get configuration for THIS case
        // -----------------------------------------------------

        var requiredForCase =
            getRequiredDocumentsForCase(
                getVisaCaseRecord(
                    currentVisaCase.sys_id
                ),
                configurationRecords
            );


        /*
         * Count required documents
         * for this case.
         */
        totalRequiredDocuments +=
            requiredForCase.length;


        /*
         * Update case-level missing count.
         */
        var caseMissingCount = 0;

        var caseCompletedCount = 0;


        // -----------------------------------------------------
        // Process each required document
        // -----------------------------------------------------

        for (
            var requiredIndex = 0;
            requiredIndex <
            requiredForCase.length;
            requiredIndex++
        ) {

            var requiredDoc =
                requiredForCase[
                    requiredIndex
                ];


            var foundDocument =
                null;


            // -------------------------------------------------
            // Find actual document for THIS case
            // -------------------------------------------------

            for (
                var uploadedIndex = 0;
                uploadedIndex <
                uploadedDocuments.length;
                uploadedIndex++
            ) {

                var uploaded =
                    uploadedDocuments[
                        uploadedIndex
                    ];


                /*
                 * Never allow a document from
                 * another Visa Case to satisfy
                 * this case's requirement.
                 */
                if (
                    uploaded.visa_case !==
                    requiredDoc.case_sys_id
                ) {

                    continue;
                }


                var requiredType =
                    normalize(
                        requiredDoc.document_type
                    );


                var requiredTypeValue =
                    normalize(
                        requiredDoc.document_type_value
                    );


                var uploadedType =
                    normalize(
                        uploaded.document_type
                    );


                var uploadedTypeValue =
                    normalize(
                        uploaded.document_type_value
                    );


                if (
                    (
                        requiredType &&
                        uploadedType ===
                        requiredType
                    ) ||
                    (
                        requiredTypeValue &&
                        uploadedTypeValue ===
                        requiredTypeValue
                    ) ||
                    (
                        requiredType &&
                        uploadedTypeValue ===
                        requiredType
                    ) ||
                    (
                        requiredTypeValue &&
                        uploadedType ===
                        requiredTypeValue
                    )
                ) {

                    foundDocument =
                        uploaded;

                    break;
                }
            }


            // -------------------------------------------------
            // COMPLETED
            // -------------------------------------------------

            var isComplete =
                (
                    foundDocument !== null &&
                    foundDocument.completed
                );


            if (isComplete) {

                totalCompletedDocuments++;

                caseCompletedCount++;

            } else {

                totalMissingDocuments++;

                caseMissingCount++;
            }


            // -------------------------------------------------
            // ADD DOCUMENT TO DIGITAL TWIN LIST
            // -------------------------------------------------

            data.documents.list.push({

                case_sys_id:
                    requiredDoc.case_sys_id,

                case_number:
                    requiredDoc.case_number,

                document_type:
                    requiredDoc.document_type,

                document_name:
                    requiredDoc.document_name,

                uploaded:
                    foundDocument !== null,

                completed:
                    isComplete,

                status:
                    foundDocument
                        ? foundDocument.document_status
                        : "Required",

                verification_status:
                    foundDocument
                        ? foundDocument.verification_status
                        : "Not Uploaded"
            });
        }


        // -----------------------------------------------------
        // STORE PER-CASE DOCUMENT COUNTS
        // -----------------------------------------------------

        currentVisaCase.required_documents =
            requiredForCase.length;

        currentVisaCase.completed_documents =
            caseCompletedCount;

        currentVisaCase.missing_documents =
            caseMissingCount;
    }


    // =========================================================
    // 13. FINAL DOCUMENT TOTALS
    // =========================================================

    data.documents.total =
        totalRequiredDocuments;


    data.documents.completed =
        totalCompletedDocuments;


    data.documents.missing =
        totalMissingDocuments;


    // =========================================================
    // 14. DOCUMENT COMPLETION %
    // =========================================================

    if (
        data.documents.total > 0
    ) {

        data.documents.percentage =
            Math.round(
                (
                    data.documents.completed /
                    data.documents.total
                ) *
                100
            );

    } else {

        /*
         * No configuration matched
         * the student's active cases.
         */
        data.documents.percentage =
            0;
    }


    // =========================================================
    // 15. UPDATE CASE MISSING DOCUMENT COUNTS
    //
    // IMPORTANT:
    //
    // We calculate the count live for the Digital Twin.
    // We do NOT modify the Visa Case record here.
    // =========================================================


    // =========================================================
    // 16. DEADLINE RISK
    //
    // 40%
    // =========================================================

    var deadlineRisk = 0;


    if (nearestDeadline) {

        var days =
            nearestDeadline.days_remaining;


        if (days <= 0) {

            deadlineRisk = 100;

        } else if (days <= 3) {

            deadlineRisk = 90;

        } else if (days <= 7) {

            deadlineRisk = 75;

        } else if (days <= 14) {

            deadlineRisk = 55;

        } else if (days <= 30) {

            deadlineRisk = 30;

        } else {

            deadlineRisk = 10;
        }
    }


    // =========================================================
    // 17. MISSING DOCUMENT RISK
    //
    // 35%
    // =========================================================

    var missingDocumentRisk =
        0;


    if (
        data.documents.total > 0
    ) {

        missingDocumentRisk =
            Math.round(
                (
                    data.documents.missing /
                    data.documents.total
                ) *
                100
            );
    }


    // =========================================================
    // 18. SLA RISK
    //
    // 25%
    // =========================================================

    var slaRisk = 0;

    var slaBreaches = 0;


    for (
        var slaIndex = 0;
        slaIndex <
        data.cases.length;
        slaIndex++
    ) {

        var madeSLA =
            normalize(
                data.cases[
                    slaIndex
                ].made_sla
            );


        if (
            madeSLA === "false" ||
            madeSLA === "0" ||
            madeSLA === "no"
        ) {

            slaBreaches++;
        }
    }


    if (
        data.cases.length > 0
    ) {

        slaRisk =
            Math.round(
                (
                    slaBreaches /
                    data.cases.length
                ) *
                100
            );
    }


    // =========================================================
    // 19. FINAL RISK SCORE
    //
    // Deadline       = 40%
    // Missing Docs   = 35%
    // SLA Delays     = 25%
    // =========================================================

    var riskScore =
        Math.round(

            (
                deadlineRisk *
                0.40
            ) +

            (
                missingDocumentRisk *
                0.35
            ) +

            (
                slaRisk *
                0.25
            )
        );


    if (riskScore > 100) {

        riskScore = 100;
    }


    if (riskScore < 0) {

        riskScore = 0;
    }


    var riskLevel =
        getRiskLevel(
            riskScore
        );


    // =========================================================
    // 20. COMPLIANCE SCORE
    //
    // Documents = 50%
    // Deadlines = 30%
    // SLA       = 20%
    // =========================================================

    var documentHealth =
        data.documents.percentage;


    var deadlineHealth =
        100 -
        deadlineRisk;


    var slaHealth =
        100 -
        slaRisk;


    var complianceScore =
        Math.round(

            (
                documentHealth *
                0.50
            ) +

            (
                deadlineHealth *
                0.30
            ) +

            (
                slaHealth *
                0.20
            )
        );


    if (
        complianceScore > 100
    ) {

        complianceScore =
            100;
    }


    if (
        complianceScore < 0
    ) {

        complianceScore =
            0;
    }


    // =========================================================
    // 21. SEND SUMMARY
    // =========================================================

    data.summary.compliance_score =
        complianceScore;


    data.summary.risk_score =
        riskScore;


    data.summary.risk_level =
        riskLevel;


    data.risk.score =
        riskScore;


    data.risk.level =
        riskLevel;


    // =========================================================
    // 22. RISK EXPLANATION
    // =========================================================

    var explanations = [];


    if (
        data.documents.missing > 0
    ) {

        explanations.push(
            "Missing or incomplete required documents: " +
            data.documents.missing
        );
    }


    if (
        nearestDeadline &&
        nearestDeadline.days_remaining <= 14
    ) {

        if (
            nearestDeadline.days_remaining <= 0
        ) {

            explanations.push(
                "A compliance deadline has passed."
            );

        } else {

            explanations.push(
                "A compliance deadline is approaching in " +
                nearestDeadline.days_remaining +
                " day(s)."
            );
        }
    }


    if (
        slaBreaches > 0
    ) {

        explanations.push(
            slaBreaches +
            " active case(s) have an SLA delay."
        );
    }


    if (
        data.documents.total > 0 &&
        data.documents.missing === 0
    ) {

        explanations.push(
            "All required documents are complete."
        );
    }


    if (
        data.documents.total === 0
    ) {

        explanations.push(
            "No required document configuration matched the active visa cases."
        );
    }


    if (
        slaBreaches === 0
    ) {

        explanations.push(
            "No SLA breach detected."
        );
    }


    if (
        explanations.length === 0
    ) {

        explanations.push(
            "No significant compliance risk factors detected."
        );
    }


    data.risk.explanation =
        explanations;


    // =========================================================
    // 23. COMPLIANCE STATE
    // =========================================================

    data.compliance_state = [];


    // ---------------------------------------------------------
    // IDENTITY
    // ---------------------------------------------------------

    data.compliance_state.push({

        name:
            "Identity Verified",

        status:
            (
                data.student.first_name &&
                data.student.last_name
            )
                ? "complete"
                : "warning"
    });


    // ---------------------------------------------------------
    // PASSPORT
    // ---------------------------------------------------------

    var passportVerified =
        false;


    for (
        var passportIndex = 0;
        passportIndex <
        data.documents.list.length;
        passportIndex++
    ) {

        var passportDoc =
            data.documents.list[
                passportIndex
            ];


        if (
            normalize(
                passportDoc.document_type
            ).indexOf(
                "passport"
            ) !== -1 &&
            passportDoc.completed
        ) {

            passportVerified =
                true;

            break;
        }
    }


    data.compliance_state.push({

        name:
            "Passport Verified",

        status:
            passportVerified
                ? "complete"
                : "warning"
    });


    // ---------------------------------------------------------
    // UNIVERSITY
    // ---------------------------------------------------------

    data.compliance_state.push({

        name:
            "University Information",

        status:
            data.student.university_name
                ? "complete"
                : "warning"
    });


    // ---------------------------------------------------------
    // VISA STATUS
    // ---------------------------------------------------------

    var visaStatus =
        normalize(
            data.student.visa_status
        );


    data.compliance_state.push({

        name:
            "Visa Status Active",

        status:
            (
                visaStatus === "active" ||
                visaStatus === "valid" ||
                visaStatus === "approved"
            )
                ? "complete"
                : "warning"
    });


    // ---------------------------------------------------------
    // REQUIRED DOCUMENTS
    // ---------------------------------------------------------

    data.compliance_state.push({

        name:
            "Required Documents",

        status:
            (
                data.documents.total > 0 &&
                data.documents.missing === 0
            )
                ? "complete"
                : "warning"
    });


    // ---------------------------------------------------------
    // SLA
    // ---------------------------------------------------------

    data.compliance_state.push({

        name:
            "SLA Compliance",

        status:
            slaBreaches === 0
                ? "complete"
                : "warning"
    });


    // =========================================================
    // 24. AI RECOMMENDATION
    // =========================================================

    if (
        data.documents.missing > 0
    ) {

        data.recommendation =
            "Complete the missing required documents before your upcoming compliance deadline.";

    } else if (
        nearestDeadline &&
        nearestDeadline.days_remaining <= 14
    ) {

        data.recommendation =
            "Review your upcoming compliance deadline and complete any required action before the due date.";

    } else if (
        slaBreaches > 0
    ) {

        data.recommendation =
            "Review the delayed case activity and follow up with your assigned advisor.";

    } else {

        data.recommendation =
            "Your compliance records currently look healthy. Continue monitoring your documents and upcoming deadlines.";
    }


    // =========================================================
    // 25. GET LATEST RISK ASSESSMENT
    // =========================================================

    var latestAssessment =
        null;


    var assessmentGR =
        new GlideRecord(
            "x_snc_visaguardi_0_risk_assessment"
        );


    assessmentGR.addQuery(
        "visa_case",
        "IN",
        caseIds.join(",")
    );


    assessmentGR.orderByDesc(
        "last_assessment_date"
    );


    assessmentGR.setLimit(1);

    assessmentGR.query();


    if (
        assessmentGR.next()
    ) {

        latestAssessment = {

            sys_id:
                assessmentGR.getUniqueValue(),

            compliance_score:
                assessmentGR.getValue(
                    "compliance_score"
                ),

            risk_level:
                assessmentGR.getDisplayValue(
                    "risk_level"
                ),

            days_remaining:
                assessmentGR.getValue(
                    "days_remaining"
                ),

            missing_documents:
                assessmentGR.getValue(
                    "missing_documents_count"
                ),

            explanation:
                assessmentGR.getValue(
                    "risk_explanation"
                ),

            assessment_status:
                assessmentGR.getDisplayValue(
                    "assessment_status"
                ),

            last_assessment_date:
                assessmentGR.getDisplayValue(
                    "last_assessment_date"
                ),

            visa_case:
                assessmentGR.getDisplayValue(
                    "visa_case"
                )
        };
    }


    data.latest_assessment =
        latestAssessment;


    // =========================================================
    // 26. FINAL DATA FOR UI
    // =========================================================

    data.summary.document_completion =
        data.documents.percentage;


    data.summary.total_documents =
        data.documents.total;


    data.summary.completed_documents =
        data.documents.completed;


    data.summary.missing_documents =
        data.documents.missing;


    data.summary.sla_breaches =
        slaBreaches;


    data.summary.deadline_risk =
        deadlineRisk;


    data.summary.document_risk =
        missingDocumentRisk;


    data.summary.sla_risk =
        slaRisk;


    // =========================================================
    // 27. HELPER:
    // GET VISA CASE RECORD
    //
    // Used because document configuration must be
    // evaluated separately for every case.
    // =========================================================

    function getVisaCaseRecord(
        sysId
    ) {

        var gr =
            new GlideRecord(
                "x_snc_visaguardi_0_visa_case"
            );


        if (
            gr.get(sysId)
        ) {

            return gr;
        }


        return null;
    }

})();
